import os,json,struct,hashlib,zlib
from Crypto.Cipher import AES
out=os.environ['OUT']; img='inputs/chall/Carmine-Falcone.raw'; pw=json.load(open('store/jobs/j000126/out/recovery.json'))['password']; offsets=[877111456,1304934584,3105492992,4591231224]; summary=[]
with open(img,'rb') as f:
 for off0 in offsets:
  f.seek(off0); d=f.read(4096); pos=12; fld={}
  try:
   while True:
    fid=d[pos]; ln=struct.unpack_from('<H',d,pos+1)[0]; val=d[pos+3:pos+3+ln]; pos+=3+ln
    if fid==0: break
    fld[fid]=val
   seed,ts,iv,start=fld[4],fld[5],fld[7],fld[9]; rounds=struct.unpack('<Q',fld[6])[0]
   ck=hashlib.sha256(hashlib.sha256(pw.encode()).digest()).digest(); c=AES.new(ts,AES.MODE_ECB)
   for _ in range(rounds): ck=c.encrypt(ck)
   mk=hashlib.sha256(seed+hashlib.sha256(ck).digest()).digest(); ct=d[pos:pos+((len(d)-pos)//16)*16]; plain=AES.new(mk,AES.MODE_CBC,iv).decrypt(ct); verified=plain[:32]==start
   p=32; chunks=[]; bm=[]
   while p+40<=len(plain):
    idx=struct.unpack_from('<I',plain,p)[0]; h=plain[p+4:p+36]; ln=struct.unpack_from('<I',plain,p+36)[0]; p+=40
    if p+ln>len(plain): bm.append({'index':idx,'length':ln,'complete':False,'available':len(plain)-p}); break
    ch=plain[p:p+ln]; p+=ln; bm.append({'index':idx,'length':ln,'complete':True,'hash_ok':hashlib.sha256(ch).digest()==h if ln else True}); chunks.append(ch)
   stream=b''.join(chunks); xml=b''; err=None
   try: xml=zlib.decompress(stream,16+zlib.MAX_WBITS)
   except Exception as e:
    try: z=zlib.decompressobj(16+zlib.MAX_WBITS); xml=z.decompress(stream); err=repr(e)
    except Exception as e2: err=repr(e2)
   name=str(off0); open(out+'/'+name+'.kdbx-prefix','wb').write(d); open(out+'/'+name+'.xml','wb').write(xml)
   summary.append({'offset':off0,'sha256_4096':hashlib.sha256(d).hexdigest(),'stream_start_verified':verified,'header_end':pos,'blocks':bm,'xml_bytes':len(xml),'xml_sha256':hashlib.sha256(xml).hexdigest(),'decompress_note':err})
  except Exception as e: summary.append({'offset':off0,'error':repr(e)})
open(out+'/versions.json','w').write(json.dumps(summary,indent=2)); print(json.dumps(summary,indent=2))
PY

